// Merges the generator output (scripts/out/*.jsonl) into the bundled puzzle set js/data/puzzles.js.
//   node scripts/build-puzzles.mjs [--per 36]
// Puzzles are generated by search (see gen-puzzles.mjs / gen-motifs.mjs); every one has a unique,
// engine-verified best first move. We only keep clear, teachable motifs and balance them by level.
import { readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { join } from 'node:path';
import { Chess } from '../js/chess/rules.js';

const here = fileURLToPath(new URL('.', import.meta.url));
const args = process.argv.slice(2);
const per = +(args[args.indexOf('--per') + 1] || 36);
const out = join(here, 'out');

const rows = [];
for (const f of readdirSync(out).filter((n) => n.startsWith('puzzles') && n.endsWith('.jsonl'))) {
  for (const line of readFileSync(join(out, f), 'utf8').split('\n')) { if (line.trim()) try { rows.push(JSON.parse(line)); } catch { /* partial line */ } }
}

const toMove = (u) => (u.length === 5 ? { from: u.slice(0, 2), to: u.slice(2, 4), promotion: u[4] } : { from: u.slice(0, 2), to: u.slice(2, 4) });
const pieceCount = (fen) => (fen.split(' ')[0].match(/[a-zA-Z]/g) || []).length;

function category(p) {
  const t = p.themes;
  if (p.mate && p.solverMoves === 1) return 'mate1';
  if (p.mate && p.solverMoves === 2) return 'mate2';
  if (p.mate) return null; // mate in 3+ is too long for this set
  if (t.includes('discoveredCheck') || t.includes('discovered')) return 'discovered';
  if (t.includes('skewer')) return 'skewer';
  if (t.includes('pin')) return 'pin';
  if (t.includes('fork')) return 'fork';
  return null;
}
function level(p, cat) {
  const n = pieceCount(p.fen);
  const s = p.depthNeeded + 2 * (p.solverMoves - 1) + (n > 8 ? 1 : 0) + (n > 12 ? 1 : 0);
  if (cat === 'mate1') return s <= 2 ? 1 : s <= 3 ? 2 : 3;
  return s <= 2 ? 1 : s <= 3 ? 2 : s <= 5 ? 3 : s <= 7 ? 4 : 5;
}

const sanLine = (p) => {
  const g = new Chess(p.fen);
  const parts = [];
  let num = +p.fen.split(' ')[5] || 1, white = g.turn() === 'w';
  p.moves.forEach((u, i) => {
    const mv = g.move(toMove(u));
    const pre = white ? `${num}.` : (i === 0 ? `${num}...` : '');
    parts.push(`${pre}${mv.san}`);
    if (!white) num++;
    white = !white;
  });
  return parts.join(' ');
};

const text = {
  mate1: ['Look for a check that leaves the king no escape.', 'Checkmate: the king is attacked and cannot move, capture the checking piece or block.'],
  mate2: ['Start with a forcing move: a check or a sacrifice that leaves only one reply.', 'A forced mate in two: after the first move every defence runs into checkmate.'],
  fork: ['Look for one move that attacks two pieces at once.', 'A fork: one piece attacks two targets, and the opponent can only save one.'],
  pin: ['Look for a piece that cannot move without exposing something more valuable behind it.', 'A pin: the pinned piece is stuck, so the attacker wins material.'],
  skewer: ['Attack the more valuable piece so it must move and exposes the piece behind it.', 'A skewer: the valuable piece in front has to move, and the piece behind it is captured.'],
  discovered: ['Move a piece out of the way to unleash an attack from a piece behind it.', 'A discovered attack: moving one piece reveals an attack by another, creating two threats at once.'],
};

const seen = new Set();
const buckets = new Map();
for (const p of rows) {
  const cat = category(p);
  if (!cat) continue;
  const key = p.fen.split(' ').slice(0, 2).join(' ');
  if (seen.has(key)) continue;
  seen.add(key);
  // skip positions that are trivially dominated (huge material edge for the side to move before the tactic)
  let g; try { g = new Chess(p.fen); } catch { continue; }
  if (g.isGameOver()) continue;
  const lv = level(p, cat);
  const b = `${cat}:${lv}`;
  (buckets.get(b) || buckets.set(b, []).get(b)).push({ ...p, cat, lv });
}

// deterministic shuffle, then pick up to `per` per bucket
let seed = 12345; const rnd = () => (seed = (seed * 1103515245 + 12345) & 0x7fffffff) / 0x7fffffff;
const picked = [];
for (const [b, arr] of [...buckets.entries()].sort()) {
  arr.sort((a, c) => a.fen.localeCompare(c.fen));
  for (let i = arr.length - 1; i > 0; i--) { const j = Math.floor(rnd() * (i + 1)); [arr[i], arr[j]] = [arr[j], arr[i]]; }
  picked.push(...arr.slice(0, per));
}
picked.sort((a, b) => a.cat.localeCompare(b.cat) || a.lv - b.lv || a.fen.localeCompare(b.fen));
const puzzles = picked.map((p, i) => ({
  id: `${p.cat}-${p.lv}-${String(i + 1).padStart(3, '0')}`,
  fen: p.fen, moves: p.moves, theme: p.cat, themes: p.themes, level: p.lv, solverMoves: p.solverMoves,
  solution: sanLine(p), hint: text[p.cat][0], explain: text[p.cat][1],
}));

const header = `// GENERATED by scripts/build-puzzles.mjs — ${puzzles.length} puzzles. Do not edit by hand.
// Every puzzle has a unique best first move verified by search; mate puzzles are re-verified by tests.
// moves = UCI: solver move, (opponent reply, solver move)...  level 1 (easiest) .. 5 (hardest).
`;
writeFileSync(join(here, '..', 'js', 'data', 'puzzles.js'), header + 'export const PUZZLES = ' + JSON.stringify(puzzles) + ';\n');
const counts = {};
for (const p of puzzles) { const k = `${p.theme} L${p.level}`; counts[k] = (counts[k] || 0) + 1; }
console.log(`read ${rows.length} rows, wrote ${puzzles.length} puzzles`);
console.log(JSON.stringify(counts));
